function advanceRegionalProgress107(z,amount){z.termProgress+=amount;z.totalProgress+=amount;if(Number.isFinite(z.demandProgress))z.demandProgress=clamp(z.demandProgress+amount,0,1)}
// Explicit regional project percentages are already scaled and must match their option text.
function noteDecision(label,axes={},tags=[],region=null,amount=1,localProgress=null){let g=v3();if(!g)return;g.decisions.push({q:s.q,label,axes:{...axes},tags:[...tags],region});for(let k of AXES)g.axisSum[k]+=axes[k]||0;g.axisCount++;for(let tag of tags)g.termActions[tag]=(g.termActions[tag]||0)+amount;for(let z of g.regions){if(region!==null&&z.id!==region)continue;if(regionMatchesTags107(z,tags)){advanceRegionalProgress107(z,localProgress??amount*LOCAL_PROGRESS_RATE107);z.development=clamp(z.development+amount*.8,0,100)}}}
function adjustRegions(tag,value){for(let z of v3().regions)if(z.sector===tag)z.attitude=clamp(z.attitude+value,-.35,.3)}
