function makeReformOffers(){let g=v3(),existing=g.offers.filter(o=>o.kept||pstate().bill?.offer===o.uid);let eligible=REFORMS.map((_,i)=>i).filter(i=>!existing.some(o=>o.catalog===i)&&!s.reforms.some(x=>x.id===i)&&!(REFORMS[i].key==='inheritance'&&g.inheritanceUsed));for(let i=eligible.length-1;i>0;i--){let j=Math.floor(rand()*(i+1));[eligible[i],eligible[j]]=[eligible[j],eligible[i]]}g.offers=existing.concat(eligible.slice(0,6).map(i=>({uid:g.nextOffer++,catalog:i,kept:false,cycle:g.cycle})));}
function reformDetail(uid){let o=v3().offers.find(x=>x.uid===uid);if(!o)return;let r=REFORMS[o.catalog];if(!s.ended){o.kept=true;save()}modal(`<span class="tag">已保留草案 · ${r.lag} 季度执行期</span><h2>${r.name}</h2><p>${r.text}</p><p>启动成本 ${fmt(reformStartCost(o.catalog,o.uid),2)}% GDP；长期潜在增长 ${r.boost>=0?'+':''}${r.boost} 个百分点。<br>完成效果：${impactText(r.values)}。</p><p>本草案已保留，轮换时不会消失。先提交议案，经权力机关通过后启动。</p><button onclick="$('modal').close()">返回</button> <button class="primary" onclick="submitReform(${uid})" ${s.ended?'disabled':''}>提交改革议案</button>`)}
function submitReform(uid){let p=pstate(),o=v3().offers.find(x=>x.uid===uid);if(!o||s.ended)return;if(p.bill){toast('先完成或撤回当前议程');return}let r=REFORMS[o.catalog];if(s.reforms.some(x=>x.id===o.catalog))return;o.kept=true;p.bill={kind:'reform',id:o.catalog,offer:uid,title:r.name+'法案',description:r.text};$('modal').close();tab='assembly';pSave()}
policies=function(){let g=v3(),authority=regime().body==='枢密院'?'枢密院':'政府';return `<div class="political-banner"><div><span class="tag">改革议程 / 第 ${g.cycle+1} 批</span><h2>长期改革，需要政治耐心。</h2><p>${authority}每 6 季度完成一批新草案。未查看草案在轮换提示确认后替换；已查看、已提交与执行中项目保留。下次窗口关闭还有 ${6-s.q%6} 季度。</p></div></div><div class="section-label"><h3>可审议草案</h3><span>点击查看即可保留草案</span></div><div class="member-grid">${g.offers.map(o=>{let r=REFORMS[o.catalog];return `<section class="card"><span class="tag">${o.kept?'已保留':'本期新草案'} / ${r.lag} 季度</span><h2>${r.name}</h2><p>${r.text}</p><div class="row"><span>启动成本</span><b>${fmt(reformStartCost(o.catalog,o.uid),2)}% GDP</b></div><button onclick="reformDetail(${o.uid})">查看与提案 →</button></section>`}).join('')||'<p>本期所有草案已处理，请等待下一批。</p>'}</div><div class="section-label"><h3>执行中与已完成项目</h3><span>通过后持续执行，不受轮换影响</span></div><div class="split">${s.reforms.map(x=>{let r=REFORMS[x.id];return `<div class="card"><span class="tag">${x.completed?'✓ 已完成':`还需 ${Math.max(0,x.ready-s.q)} 季度`}</span><h2>${r?.name||'旧版改革项目'}</h2><p>${r?.text||''}</p><p>${x.completed?'效果已计入国家指标':'完成时兑现效果，项目已占用启动预算。'}</p></div>`}).join('')||'<p class="note">尚无执行项目。</p>'}</div>`};
reform=function(i){let o=v3().offers.find(x=>x.catalog===i);if(o)reformDetail(o.uid)};proposeReform=reform;
voteBill=function(){let p=pstate(),b=p.bill;if(!b||!spendAction('vote'))return;let count=billPassRate104();if(count>=threshold()){if(b.kind==='budget'){let before={...s.policies};if(spend(b.policies)<spend())p.memory.cuts++;s.policies={...b.policies};draft={...s.policies};let axes={market:clamp((before.income-s.policies.income)/3,-4,4),welfare:clamp((s.policies.welfare-before.welfare)+(s.policies.health-before.health),-4,4),military:clamp(s.policies.security-before.security,-3,3)};let tags=[];if(s.policies.education>before.education)tags.push('technology');if(s.policies.infrastructure>before.infrastructure)tags.push('industry','agriculture');if(s.policies.welfare>before.welfare||s.policies.health>before.health)tags.push('welfare');noteDecision('通过财政预算',axes,tags,null,.5)}else{let r=REFORMS[b.id];if(!r||s.reforms.some(x=>x.id===b.id)){p.bill=null;pSave();return}mod({cost:reformStartCost(b.id,b.offer)});s.reforms.push({id:b.id,key:r.key,ready:s.q+r.lag,boost:r.boost,completed:false,effectsApplied:false});v3().offers=v3().offers.filter(x=>x.uid!==b.offer);noteDecision('启动'+r.name,r.axes,r.tags);if(r.key==='inheritance')v3().inheritanceUsed=true}p.passed.push({title:b.title,q:s.q,votes:count,passRate:count});mod({approval:1,stability:1});log('议程通过',`${b.title}院内支持率 ${fmt(count,1)}%，达到 ${threshold()}% 门槛，开始实施。`);p.bill=null;p.confidenceLoss=0;toast('议程通过')}else{mod({approval:-2,stability:-1});p.confidenceLoss++;noteDecision('议程表决失败',{authority:0});log('议程受阻',`${b.title}院内支持率 ${fmt(count,1)}%，未达到 ${threshold()}% 门槛。`);toast('提案保留，请继续协商')}pSave()};
function completeReforms(){for(let x of s.reforms){if(x.completed||s.q<x.ready)continue;let r=REFORMS[x.id];x.completed=true;if(!x.effectsApplied&&r){mod(r.values);if(r.key==='inheritance'){s.debt*=.5;adjustRegions('trade',-.2);adjustRegions('technology',-.1)}if(r.key==='fund')v3().fund=s.gdp*.02;noteDecision('完成'+r.name,r.axes,r.tags);log('改革完成',r.name+'：'+impactText(r.values)+(r.key==='inheritance'?'。已清偿完成时 50% 的公债；贸易区支持修正 -20%，科技区 -10%。':''));x.effectsApplied=true}}if(v3().fund>0){let earnings=v3().fund*.03/6;mod({cost:-earnings/s.gdp*100});v3().fund+=earnings*.25;log('主权基金季报',`收益 ${fmt(earnings,2)} 十亿元用于偿债，基金资产 ${fmt(v3().fund,2)} 十亿元。`)}}
Object.assign(TASKS,{industry:'工业与就业',agriculture:'乡村与农业',technology:'科技创新',green:'生态与文化'});
