meetMember=function(id){let m=pstate().members[id];if(!m)return;modal(`<span class="tag">${esc(m.role)} / ${esc(m.region)}</span><h2>会见${m.name}</h2><p><b>政治倾向：${TRAITS[m.trait].name}</b><br>${TRAITS[m.trait].desc}</p><p>${m.name}希望政府回应${m.region}的${PROFILES[m.regionId].need}。每人每季一次，消耗 1 行动点；选择会计入统治倾向评估。</p><div class="choices">${Object.entries(MEMBER_CHOICES).map(([k,o])=>`<button onclick="memberAnswer(${id},'${k}')">${o.label}<small>${o.detail}</small></button>`).join('')}<button onclick="$('modal').close()">结束会见</button></div>`)};
memberAnswer=function(id,kind){let p=pstate(),m=p.members[id],o=MEMBER_CHOICES[kind];if(!m||!o||!spendAction('member'+id))return;m.last=s.q;m.relation=clamp(m.relation+o.rel,0,100);p.factions[m.faction].relation=clamp(p.factions[m.faction].relation+o.faction,0,100);mod(o.values);let tags=o.local?[v3().regions[m.regionId].sector]:(o.tags||[]);noteDecision(`会见${m.name}：${o.label}`,o.axes,tags,o.local?m.regionId:null);log('成员会见',`${m.name}（${TRAITS[m.trait].name}）：${o.label}。`);$('modal').close();pSave()};
const dealV2=deal;deal=function(id,kind){let before=pstate().ap;dealV2(id,kind);if(pstate().ap<before){noteDecision('派系协商：'+kind,kind==='law'?{law:3,authority:-1}:kind==='grant'?{welfare:2,elite:2}:{welfare:2,populism:1},kind==='promise'?['technology']:[]);save()}};
const courtV2=courtAction;courtAction=function(kind){let before=pstate().ap;courtV2(kind);if(pstate().ap<before){noteDecision('司法互动：'+kind,kind==='pressure'?{authority:5,law:-5}:kind==='protect'?{law:4,authority:-2}:{law:2});save()}};
const appointV2=appointOfficial;appointOfficial=function(k,id){let before=pstate().ap;appointV2(k,id);if(pstate().ap<before){let c=pstate().candidates[id];noteDecision(`任命${c.name}为${office(k)}`,TRAIT_AXES[c.trait]);save()}};
const removeV2=removeOfficial;removeOfficial=function(k){let c=pstate().candidates[pstate().cabinet[k].candidate];noteDecision('撤换'+c.name,{authority:c.achievements>=8?3:1,elite:1});removeV2(k)};
setTask=function(k,v){if(s.ended||!TASKS[v]||!pstate().cabinet[k])return;let old=pstate().cabinet[k].task;pstate().cabinet[k].task=v;if(old!==v){let once='taskscore:'+k+':'+s.q;if(!pstate().lastAction[once]){noteDecision(`${office(k)}任务：${TASKS[v]}`,{economy:{market:2},social:{welfare:3},order:{authority:2},law:{law:3},industry:{market:-1,nation:1},agriculture:{welfare:2},technology:{market:1},green:{green:3}}[v]||{});pstate().lastAction[once]=1}}save();toast('任务已更新，下季度执行')};
runCabinet=function(){let p=pstate(),r=regime();for(let [k,item]of Object.entries(p.cabinet)){if(!item){mod({stability:k==='head'?-3:-.25});continue}let c=p.candidates[item.candidate],t=TRAITS[c.trait];c.tenure++;let scale=.65*(.4+c.skill/140)*(.6+c.loyalty/200)*(k==='head'?(r.head==='宰相'?1.6:1):.22);let success=rand()<(.48+c.skill/220+c.loyalty/600),v={approval:t.approval*scale,stability:t.stability*scale,confidence:t.confidence*scale};if(k==='head'||k==='justice')v.judicial=t.justice*scale*(k==='justice'?2:1);if([3,5,7].includes(c.trait))v.cost=.06*scale;if([2,8].includes(c.trait))v.cost=-.035*scale;if(c.trait===6){v.cost=.06*scale;v.capitalStock=.12*scale}if(item.task==='economy'){v.cost=(v.cost||0)-.04*scale;v.confidence+=.5*scale;v.approval-=.35*scale}if(item.task==='social'){v.cost=(v.cost||0)+.08*scale;v.approval+=.7*scale}if(item.task==='order'){v.stability+=.6*scale;if(c.trait===4)v.judicial=(v.judicial||0)-.6*scale}if(item.task==='law')v.judicial=(v.judicial||0)+(c.trait===4?-.2:.7)*scale;
let departmentTask=departmentTask105(k,item,c);if(departmentTask)for(let [metric,value]of Object.entries(departmentValues105(departmentTask,c)))v[metric]=(v[metric]||0)+value;
if(success){c.achievements+=scale*1.5;if(k==='education')v.human=(v.human||0)+.4;if(k==='environment')v.capitalStock=(v.capitalStock||0)+.3;if(k==='health'||k==='culture')v.approval+=.3;if(k==='labour'){v.unemployment=(v.unemployment||0)-.05;v.approval+=.15}if(k==='foreign')v.confidence+=.35;if(k==='defence'||k==='interior')v.stability+=.3;if(k==='deputy')v.relation=.15;let tag={industry:'industry',agriculture:'agriculture',technology:'technology',green:'green',social:'welfare',order:'security'}[item.task];if(tag){v.cost=(v.cost||0)+.02*scale;for(let z of v3().regions)if(regionMatchesTags107(z,[tag])){advanceRegionalProgress107(z,.12*LOCAL_PROGRESS_RATE107);z.development=clamp(z.development+.08,0,100)}}}else{for(let n in v)if(n!=='cost')v[n]*=.3;v.stability-=.3;c.achievements-=.25}if(departmentTask){if(!success&&v.cost<0)v.cost*=.3;if(v.growth)v.duration=1;recordDepartmentTask105(k,departmentTask,success)}mod(v);let report={q:s.q,title:`${office(k)} ${c.name}：${success?'完成任务':'执行受阻'}`,text:`${t.name}；方向：${TASKS[item.task]}${departmentTask&&item.task==='balanced'?' → '+departmentTask.name:''}；采取${METHODS[c.trait]}。${departmentTask?departmentImpact105(v):impactText(v)}。`};p.reports.unshift(report);if(k==='head')log(report.title,report.text)}p.reports=p.reports.slice(0,160)};
function regionalEstimate(z){let fulfilled=clamp(z.termProgress,0,1),unmet=-.2*(1-fulfilled),bonus=.08*Math.max(0,Math.min(1,z.termProgress-1)),development=clamp((z.development-50)/500,-.07,.07),fit=unmet+bonus+z.attitude+development;return {unmet,bonus,development,fit,share:clamp(s.approval*(1+fit),1,99)}}
function electionForecast(){let rows=v3().regions.map(z=>({...regionalEstimate(z),id:z.id,name:z.name,weight:z.weight,progress:z.termProgress}));return {q:s.q,base:s.approval,rows,total:rows.reduce((a,z)=>a+z.share*z.weight/100,0)}}
function holdElection(){let g=v3(),r=regime(),result=electionForecast();result.won=result.total>50;g.elections.push(result);for(let row of result.rows){let z=g.regions[row.id];z.lastResult=row.share;z.termProgress=0}g.termActions={};if(r.democratic){if(!result.won){setGameEnd107(`选举失利：全国加权得票率 ${fmt(result.total)}%，未超过 50%。`);beginSettlement('民主选举失利')}else{s.mandates++;log('全国选举结果',`单轮两方多数决：政府 ${fmt(result.total)}%，反对阵营 ${fmt(100-result.total)}%。赢得第 ${s.mandates} 次选举。`)}}else{let change=(result.total-50)*.2;mod({stability:change});log('选举与权力评议',`加权支持 ${fmt(result.total)}%，稳定变化 ${fmt(change)}。`)}let gov=Math.round(clamp(result.total,10,85));distributeElectionSeats107(gov);}
politics=function(){let r=regime(),g=v3(),forecast=electionForecast();return `<div class="political-banner"><div><span class="tag">地区民意 / ${r.election?'单轮多数选举':'权力评议'}</span><h2>${r.democratic?'每一张地区选票，都有来由。':'民意与地方利益共同支撑统治。'}</h2><p>每年 6 季度，每届 24 季度。${r.democratic?'两方单轮选举，全国按地区人口权重计票，超过 50% 才胜选；第 48 季度结束第二任期并结算。':'第 48 季度首次询问结算，继续后每 12 季度再次询问；稳定低于 20 将结束游戏。'}</p></div></div><div class="metrics political-metrics">${metric('全国支持率',fmt(s.approval),'%','地区选票的基准')}${metric('当前加权选票预测',fmt(forecast.total),'%',regime().democratic?'超过 50% 才能胜选':'地方认同影响稳定',forecast.total>50)}${metric('距选举 / 评议',TERM-s.q%TERM,'季度','最后 6 季度增加竞选事件')}${metric('本届已过',s.q%TERM,'季度',`${fmt(s.q/6)} 年执政`)}</div><div class="card"><h3>地区选票如何计算</h3><p>地区票率 = 全国支持率 ×（1 − 未满足诉求扣减 + 超额履约加成 + 历史政策修正 + 发展状况修正）。未回应诉求最多扣 20%，超过基本目标最多加 8%。例如：全国 70%、诉求完全未回应且其他修正为 0 → 56%。每个地区按人口权重计入全国票率。以下是当前预测，选举完成后会保留实际结果。</p></div><div class="region-grid">${g.regions.map(z=>{let p=PROFILES[z.id],e=regionalEstimate(z);return `<article class="card"><span class="tag">${z.isCapital?'首都地区 · ':''}${p.name} / <span data-guide="population">人口权重 ${z.weight}%</span></span><h2>${z.name}</h2><p><b>${p.geo}</b><br>产业：${p.industry}<br>宗教：${p.religion}<br><span data-guide="base">社会基本盘：${p.base}</span><br>经济与发展：${p.growth}；<span data-guide="development">发展指数 ${fmt(z.development,0)}/100</span></p><div class="row"><span>本届诉求</span><b>${p.need}</b></div><div class="bar"><i style="width:${Math.min(100,z.termProgress*100)}%"></i></div><p>兑现 ${fmt(Math.min(100,z.termProgress*100),0)}% · 未满足扣减 ${fmt(e.unmet*100,0)}% · 超额履约 +${fmt(e.bonus*100,0)}% · 政策修正 ${fmt(z.attitude*100)}% · 发展修正 ${fmt(e.development*100)}%</p><div class="row"><span>当前票率预测</span><b>${fmt(e.share)}%</b></div><div class="row"><span>上次实际得票</span><b>${z.lastResult===null?'尚未投票':fmt(z.lastResult)+'%'}</b></div></article>`}).join('')}</div><div class="card" style="margin-top:20px"><h3>历次投票结果</h3>${g.elections.map(e=>`<details><summary>${date(e.q)} · 政府 ${fmt(e.total)}% / 反对阵营 ${fmt(100-e.total)}% · ${e.won?'多数支持':'未获多数'}</summary><div class="table-wrap"><table><thead><tr><th>地区</th><th>权重</th><th>政府得票</th><th>基准支持</th><th>综合地区修正</th></tr></thead><tbody>${e.rows.map(z=>`<tr><td>${z.name}</td><td>${z.weight}%</td><td>${fmt(z.share)}%</td><td>${fmt(e.base)}%</td><td>${fmt(z.fit*100)}%</td></tr>`).join('')}</tbody></table></div></details>`).join('')||'<p>首次投票在第 24 季度结束时举行。</p>'}</div>`};
function option(label,detail,values={},axes={},tags=[]){return {label,detail,values,axes,tags}}
function eventFrom(title,text,options,type='political'){return {title,text,options,type}}
regionalEvent=function(){let m=pick(pstate().members),z=v3().regions[m.regionId],profile=PROFILES[z.id];return {type:'regional',title:`${z.name}要求兑现${profile.name}议程`,text:`${m.role}${m.name}（${TRAITS[m.trait].name}）要求政府回应“${profile.need}”。本届诉求完成度为 ${fmt(Math.min(100,z.termProgress*100),0)}%。`,member:m.id,faction:m.faction,region:z.id,options:[{...option('批准地区发展项目','支出 0.45% GDP；支持 +2；个人关系 +10；派系 +8；地区诉求进度 +70 个百分点。',{cost:.45,approval:2},{welfare:2,nation:1},[z.sector]),member:10,faction:8,memory:'compromises'},{...option('以公开协商推动低成本试点','支出 0.12% GDP；司法独立 +2；个人关系 +5；地区诉求进度 +35 个百分点。',{cost:.12,judicial:2},{law:2,authority:-1},[z.sector]),member:5,faction:4,progress:.35},{...option('暂不安排资源','信心 +1；个人关系 -8；派系 -7；地区诉求保持未兑现。',{confidence:1},{market:1,welfare:-1}),member:-8,faction:-7}]}}
ministerEvent=function(){let p=pstate(),slots=Object.keys(p.cabinet).filter(k=>p.cabinet[k]);if(!slots.length)return regionalEvent();let slot=pick(slots),c=p.candidates[p.cabinet[slot].candidate],t=TRAITS[c.trait],values={approval:t.approval*2,stability:t.stability*2,confidence:t.confidence*2,judicial:t.justice*2},tags={5:['welfare'],6:['industry'],7:['industry','agriculture'],8:['trade'],3:['welfare'],1:['technology']}[c.trait]||[];if([3,5,6,7].includes(c.trait))values.cost=.35;return {type:'minister',title:`${office(slot)}的${t.name}提案`,text:`${c.name}建议通过${METHODS[c.trait]}完成本季任务。${t.desc}`,slot,candidate:c.id,options:[{...option('支持其完整方案','忠诚 +7；'+impactText(values)+'。',values,TRAIT_AXES[c.trait],tags),loyalty:7},{...option('缩小试点，保留公开审查','忠诚 -2；司法独立 +2；信心 +1；相关地区诉求进度 +35 个百分点。',{judicial:2,confidence:1},{law:2},tags),loyalty:-2,progress:.35},{...option('否决方案并要求其负责','忠诚 -10；稳定 -2；低忠诚可能导致辞职。',{stability:-2},{authority:2}),loyalty:-10}]}}
judicialEvent=function(){return eventFrom(`${regime().court}要求独立审查`,pstate().memory.judicialPressure?'过往行政干预引发法官抗议。法院要求公开决策依据并保障司法任期。':'法院对公共项目、行政任命与政府采购开展独立审查，要求政府提供材料。',[option('接受审查并纠正程序','司法独立 +4；信心 +2；一次性支出 0.12% GDP。',{judicial:4,confidence:2,cost:.12},{law:5,authority:-3}),option('依法申请复议','司法独立 +1；支持 +1；稳定 -1。',{judicial:1,approval:1,stability:-1},{law:2}),{...option('要求法院服从行政安排','司法独立 -9；支持 -3；短期稳定 +1。',{judicial:-9,approval:-3,stability:1},{authority:5,law:-5}),memory:'judicialPressure'}],'court')};
campaignEvent=function(){let g=v3(),p=pstate(),bad=g.regions.reduce((a,z)=>regionalEstimate(z).share<regionalEstimate(a).share?z:a),theme=p.memory.broken?'失信承诺':p.memory.judicialPressure?'司法干预':p.memory.cuts?'公共服务削减':p.memory.dismissals?'频繁撤换官员':'地区发展不均';return {type:'election',title:`选前争论：${theme}`,text:`距投票还有 ${TERM-s.q%TERM} 季度。反对阵营聚焦你的${theme}；${bad.name}是目前最薄弱的地区。全国预测 ${fmt(electionForecast().total)}%，政府需要超过 50%。`,region:bad.id,options:[option('回应薄弱地区的具体诉求','支出 0.65% GDP；支持 +3；该地区诉求进度 +70 个百分点。',{cost:.65,approval:3},{welfare:2,populism:2},[bad.sector]),option('捍卫财政纪律，公布支出账目','支持 -2；信心 +4；司法独立 +2。',{approval:-2,confidence:4,judicial:2},{market:2,law:2}),{...option('承诺保持内阁稳定，联合各派背书','支持 +2；官员忠诚 +3；两季内不得强制撤换，否则支持 -4。',{approval:2},{elite:2}),retain:true}]}};
function economicEvent(){return pick([
eventFrom('工业订单下降','制造企业订单减少，工会要求政府防止永久性失业。',[option('购买国产设备、支持更新','支出 0.5% GDP；失业 -0.4；信心 +1。',{cost:.5,unemployment:-.4,confidence:1},{market:-2,nation:2},['industry']),option('开放竞争与出口融资','支出 0.2% GDP；增长压力 +0.4，持续 6 季；稳定 -1。',{cost:.2,growth:.4,stability:-1},{market:4},['trade']),option('让企业自行调整','失业 +0.5；信心 +1；支持 -2。',{unemployment:.5,confidence:1,approval:-2},{market:3,welfare:-2})],'economy'),
eventFrom('生活成本与能源价格','能源价格上涨正在挤压家庭实际收入。',[option('定向补贴低收入家庭','支出 0.3% GDP；支持 +3；通胀 +0.2。',{cost:.3,approval:3,inflation:.2},{welfare:3},['welfare']),option('全面冻结价格并国家采购','支出 0.65% GDP；通胀 -0.5；信心 -3；稳定 +2。',{cost:.65,inflation:-.5,confidence:-3,stability:2},{authority:3,market:-4,populism:2},['industry']),option('维持市场定价','通胀 +0.4；支持 -2；信心 +2。',{inflation:.4,approval:-2,confidence:2},{market:3})],'economy'),
eventFrom('乡村信贷紧缩','农业合作社缺少春耕资金，农村代表担忧减产与收入下降。',[option('提供农业担保与水利资金','支出 0.35% GDP；支持 +2；失业 -0.2。',{cost:.35,approval:2,unemployment:-.2},{welfare:2,market:-1},['agriculture']),option('允许私人资本整合农场','增长压力 +0.3；失业 +0.3；信心 +2。',{growth:.3,unemployment:.3,confidence:2},{market:4,elite:1},['trade']),option('维持预算不干预','支持 -2；增长压力 -0.2。',{approval:-2,growth:-.2},{welfare:-2})],'economy'),
eventFrom('新兴产业投资机会','研究团队提出扩大技术园区，也有人质疑补贴是否会被少数企业占用。',[option('公开竞标的研发基金','支出 0.4% GDP；人力资本 +2；信心 +2。',{cost:.4,human:2,confidence:2},{law:2,welfare:1},['technology']),option('由国家控股主导园区','支出 0.6% GDP；基建 +3；稳定 +1。',{cost:.6,capitalStock:3,stability:1},{market:-3,authority:2},['technology','industry']),option('仅提供贸易与准入便利','信心 +3；支持 -1。',{confidence:3,approval:-1},{market:4},['trade'])],'economy'),
eventFrom('公共债务融资窗口','债券投资者要求可信的财政路径；社会团体反对以紧缩削减服务。',[option('渐进调整并保护基本服务','信心 +2；支持 +1；支出 0.1% GDP。',{confidence:2,approval:1,cost:.1},{welfare:1,law:1},['welfare']),option('削减临时项目偿还债务','债务减少 0.5% GDP；支持 -3；稳定 -2。',{cost:-.5,approval:-3,stability:-2},{market:3,welfare:-3}),option('扩大投资以增长消化债务','支出 0.7% GDP；增长压力 +0.5；通胀 +0.2。',{cost:.7,growth:.5,inflation:.2},{market:-2,nation:2},['industry'])],'economy')])}
function extraEvent(){let g=v3();if(s.stability<40)return eventFrom('地方叛乱与秩序危机','武装地方团体阻断交通，民众要求恢复安全与公共服务。军方和地方代表提出不同方案。',[option('政治谈判并恢复地方服务','支出 0.5% GDP；稳定 +5；司法独立 +2。',{cost:.5,stability:5,judicial:2},{law:3,welfare:2,authority:-1},['security','welfare']),option('依法限定范围的安全行动','支出 0.35% GDP；稳定 +4；支持 -1。',{cost:.35,stability:4,approval:-1},{military:2,law:1},['security']),option('实行紧急统治与全面动员','稳定 +7；支持 -5；司法独立 -8；增长压力 -0.4。',{stability:7,approval:-5,judicial:-8,growth:-.4},{military:4,authority:5,law:-4},['security'])],'rebellion');
if(s.q-g.lastOlympics>=12&&rand()<Math.min(.4,.025+g.sports*.035)){g.lastOlympics=s.q;return eventFrom('获得奥运主办权的机会',`国家体育基础为 ${g.sports}/10，国际奥委会邀请提交最终主办方案。大型项目既能创造岗位，也可能增加公共债务。`,[option('接受并实行公开预算监督','支出 1.8% GDP；支持 +6；失业 -0.6；信心 +2。',{cost:1.8,approval:6,unemployment:-.6,confidence:2},{nation:2,populism:1,law:2},['industry','welfare']),option('国家集中动员举办盛会','支出 2.5% GDP；支持 +9；稳定 +3；司法独立 -2。',{cost:2.5,approval:9,stability:3,judicial:-2},{nation:4,authority:3,populism:3},['industry']),option('放弃申办，保留财政空间','支持 -1；信心 +3。',{approval:-1,confidence:3},{market:2,populism:-1})],'olympics')}
return pick([
eventFrom('邻国提出自由贸易协定','降低关税可能扩大出口，但受到竞争的行业要求保护。',[option('签署协定并培训转岗工人','支出 0.3% GDP；信心 +4；增长压力 +0.4。',{cost:.3,confidence:4,growth:.4},{market:4,welfare:1,nation:-1},['trade','technology']),option('保留战略产业保护条款','信心 +1；稳定 +2；回应工业诉求。',{confidence:1,stability:2},{nation:3,market:-1},['industry']),option('拒绝协定，强调经济自主','支持 +1；信心 -3；增长压力 -0.2。',{approval:1,confidence:-3,growth:-.2},{nation:4,market:-3})],'international'),
eventFrom('边境紧张与军备争论','边境巡逻发生摩擦，军方要求升级装备，外交部门主张建立热线。',[option('建立热线并邀请第三方观察','稳定 +2；信心 +2。',{stability:2,confidence:2},{law:2,military:-2},['security']),option('有限增强防御力量','支出 0.45% GDP；稳定 +3；支持 +1。',{cost:.45,stability:3,approval:1},{military:3,nation:2},['security','industry']),option('宣布全面军事优先','支出 1% GDP；稳定 +4；信心 -4；司法独立 -3。',{cost:1,stability:4,confidence:-4,judicial:-3},{military:5,nation:4,authority:3},['security'])],'military'),
eventFrom('洪灾与重建安排','暴雨破坏交通与农田，灾区代表要求政府迅速协调重建。',[option('公开救灾与韧性工程','支出 0.65% GDP；稳定 +3；支持 +2。',{cost:.65,stability:3,approval:2},{welfare:2,green:2,law:1},['agriculture','green']),option('军政集中救援','支出 0.45% GDP；稳定 +4；司法独立 -1。',{cost:.45,stability:4,judicial:-1},{military:2,authority:2},['security']),option('依靠地方与私人保险','支出 0.1% GDP；支持 -3；增长压力 -0.3。',{cost:.1,approval:-3,growth:-.3},{market:3,welfare:-2})],'disaster'),
eventFrom('全国文化节的主张','文化团体希望获得公共资助，地方社群要求保护本地语言与表达空间。',[option('资助多元文化和地方创作','支出 0.25% GDP；支持 +3；失业 -0.2；文化基础 +1。',{cost:.25,approval:3,unemployment:-.2,culture:1},{welfare:2,law:2,authority:-1},['green','welfare']),option('举办国家主题文化盛典','支出 0.3% GDP；支持 +4；稳定 +1；文化基础 +1。',{cost:.3,approval:4,stability:1,culture:1},{nation:4,populism:2},['welfare']),option('交由商业赞助','信心 +2；支持 -1。',{confidence:2,approval:-1},{market:3},['trade'])],'culture'),
eventFrom('政治抗议与公共广场','学生与工会组织和平集会，要求政府解释近期政策取舍。',[option('保护集会并公开答辩','司法独立 +3；支持 +2；短期稳定 -1。',{judicial:3,approval:2,stability:-1},{law:4,authority:-3}),option('与代表协商限期让步','支出 0.2% GDP；稳定 +3；支持 +1。',{cost:.2,stability:3,approval:1},{welfare:2,populism:1},['welfare']),option('限制集会并要求恢复秩序','稳定 +4；支持 -4；司法独立 -5。',{stability:4,approval:-4,judicial:-5},{authority:4,law:-4})],'protest'),
eventFrom('国家体育事业的下一步','体育协会希望扩展基层设施，职业俱乐部则希望获得税收便利。',[option('建设社区体育设施','支出 0.25% GDP；支持 +2；体育基础 +1。',{cost:.25,approval:2,sports:1},{welfare:2,nation:1},['welfare']),option('投资国家竞技训练中心','支出 0.4% GDP；体育基础 +2；支持 +1。',{cost:.4,sports:2,approval:1},{nation:3,elite:1}),option('鼓励商业联赛自筹资金','信心 +1；体育基础 +0.5。',{confidence:1,sports:.5},{market:3},['trade'])],'sports')])}
function politicalEventForQuarter(){let p=pstate(),phase=s.q%TERM;if(regime().election&&phase>=18)return campaignEvent();let courtChance=p.highCourtStreak>=4?.45:p.judicial>=70?.25:.12;if(rand()<courtChance)return judicialEvent();let roll=rand();if(roll<.45)return regionalEvent();if(roll<.75)return ministerEvent();let e=institutionEvent();e.options.forEach((o,i)=>o.axes=[{law:3,authority:-2},{elite:3,welfare:1},{authority:4,law:-3,nation:2}][i]);return e}
function queueQuarterEvents(){let g=v3();let mandatory=[economicEvent(),politicalEventForQuarter(),extraEvent()];g.eventsGenerated=mandatory.length;g.eventsChosen=0;for(let e of mandatory)pushEvent(e);if(s.q%6===0)pushEvent({type:'reform-window',title:'结构性改革窗口关闭',text:`${regime().body==='枢密院'?'枢密院':'政府'}已完成下一批改革草案。确认后，未查看草案将被替换；已查看、已提交、正在执行的项目保留。`,options:[option('确认并公布新一批草案','更新改革窗口，不改变正在执行的项目。')]})}
resolvePolitical=function(i){let p=pstate(),g=v3(),e=p.current,o=e?.options[i];if(!o||s.ended)return;if(e.type==='reform-window'){g.cycle++;makeReformOffers()}else{mod(o.values||{});if(o.memory)p.memory[o.memory]++;if(o.faction&&e.faction!==undefined)p.factions[e.faction].relation=clamp(p.factions[e.faction].relation+o.faction,0,100);if(o.member&&e.member!==undefined&&p.members[e.member])p.members[e.member].relation=clamp(p.members[e.member].relation+o.member,0,100);if(o.loyalty&&e.candidate!==undefined){let c=p.candidates[e.candidate];c.loyalty=clamp(c.loyalty+o.loyalty,0,100);if(c.loyalty<30&&p.cabinet[e.slot]?.candidate===c.id){p.cabinet[e.slot]=null;mod({stability:-3,approval:-2});log('官员主动辞职',c.name+'辞职')}}if(o.retain){Object.values(p.cabinet).forEach(x=>{if(x)p.candidates[x.candidate].loyalty=clamp(p.candidates[x.candidate].loyalty+3,0,100)});p.promises.push({label:'内阁连续性承诺',description:'两季度内不强制撤换官员',type:'retain',dismissals:p.memory.dismissals,deadline:s.q+2,status:'pending'})}noteDecision(e.title+'：'+o.label,o.axes||{},o.tags||[],e.region??null,o.progress??1,o.progress??null);if(!e.constitutionalSpecial)g.eventsChosen++}log(e.title,`${o.label}。${o.detail||''}`);p.current=p.queue.shift()||null;$('modal').close();record();checkPoliticalEnd();if(s.ended)beginSettlement(s.ended);else if(!p.current)finishQuarter();save();render();if(s.ended)endDialog();else if(p.current)showPoliticalEvent();else if(g.settlementDue)showSettlementPrompt()};
showPoliticalEvent=function(){let e=pstate().current;if(!e)return;let g=v3();modal(`<span class="tag">${date()} / 季度事件已回复 ${g.eventsChosen} / 至少 3</span><h2>${esc(e.title)}</h2><p>${esc(e.text)}</p><div class="choices">${e.options.map((o,i)=>`<button onclick="resolvePolitical(${i})">${esc(o.label)}<small>${esc(o.detail||'')}</small></button>`).join('')}</div><p class="note">回复不消耗政治行动点，选择会计入地区诉求与任期评估。尚待回复 ${pstate().queue.length+1} 件。</p>`)};
