function assessment(){let g=v3(),n=Math.max(1,g.axisCount),dec=AXES.map(k=>clamp(50+g.axisSum[k]/n*14,0,100)),avg=k=>{let vals=s.history.map(h=>h[k]).filter(Number.isFinite);return vals.length?vals.reduce((a,b)=>a+b,0)/vals.length:snapshot()[k]||50};let outcome=[clamp(100-(s.policies.income+s.policies.corporate+s.policies.vat)*.65,0,100),clamp((s.policies.welfare+s.policies.health+s.policies.education)*3.8-s.unemployment,0,100),100-pstate().judicial,pstate().judicial,50,clamp(s.policies.security*12,0,100),clamp(30+(s.reforms.some(x=>x.key==='green')?35:0)+(g.termActions.green||0)*2,0,100),clamp((s.approval+avg('approval'))/2,0,100),clamp(40+pstate().candidates.filter(c=>c.achievements>8).length*2,0,100)];let vector=dec.map((v,i)=>v*.7+outcome[i]*.3);let list=regime().democratic?DEMO_IDEOLOGIES:[...NONDEMO_IDEOLOGIES,...(g.socialist?SOCIALIST_IDEOLOGIES:[])];let fits=list.map(([name,target])=>({name,percent:clamp(Math.round(100-Math.sqrt(target.reduce((a,t,i)=>a+(t-vector[i])**2,0)/AXES.length)),0,100),distance:target.reduce((a,t,i)=>a+(t-vector[i])**2,0)})).sort((a,b)=>b.percent-a.percent||a.distance-b.distance);return {fits:fits.slice(0,3),all:fits,vector,decisions:g.decisions.length,averages:{approval:avg('approval'),unemployment:avg('unemployment'),stability:avg('stability')}}}
function beginSettlement(reason){if(s.adminMode||!v3())return;setGameEnd107(s.ended||reason);v3().settlementDue=false;v3().quarterOpen=false;pstate().current=null;pstate().queue=[];record();v3().settlement={q:s.q,reason:s.ended,assessment:assessment(),final:snapshot()};tab='settlement'}
function seriesChart(key,label,unit='%',height=170){let hs=s.history,values=hs.map(h=>h[key]).filter(Number.isFinite);if(!values.length)return '<p>旧存档没有该指标的历史数据。</p>';let lo=Math.min(...values),hi=Math.max(...values);if(hi-lo<1){lo-=.5;hi+=.5}else{let pad=(hi-lo)*.12;lo-=pad;hi+=pad}let start=hs[0].q,end=hs.at(-1).q,x=q=>45+(q-start)/Math.max(1,end-start)*550,y=v=>height-28-(v-lo)/(hi-lo)*(height-48);let paths=[],run=[];for(let h of hs){if(Number.isFinite(h[key]))run.push(`${x(h.q)},${y(h[key])}`);else if(run.length){paths.push(run);run=[]}}if(run.length)paths.push(run);return `<svg viewBox="0 0 620 ${height}" class="history-chart" role="img" aria-label="${label}完整历史折线图">${[0,1,2].map(i=>{let v=lo+(hi-lo)*i/2;return `<line x1="45" y1="${y(v)}" x2="595" y2="${y(v)}" stroke="var(--line)"/><text x="2" y="${y(v)+4}">${fmt(v,Math.abs(v)>999?0:1)}</text>`}).join('')}${paths.map(run=>`<polyline points="${run.join(' ')}" stroke="var(--green)" stroke-width="2.5" fill="none"/>`).join('')}<text x="45" y="${height-5}">第 ${start} 季度</text><text x="510" y="${height-5}">第 ${end} 季度</text></svg>`}
const SERIES=[['gdp','名义 GDP','十亿元'],['growth','实际年化增长率','%'],['inflation','通货膨胀率','%'],['unemployment','失业率','%'],['debt','债务 / GDP','%'],['balance','财政余额 / GDP','%'],['rate','政策利率','%'],['yield','国债收益率','%'],['confidence','投资者信心','/100'],['approval','公众支持率','%'],['judicial','司法独立度','/100'],['stability','政治稳定度','/100']];
function settlementPage(){let g=v3(),report=g.settlement||{q:s.q,reason:'任期进行中 · 当前评估预览',assessment:assessment(),final:snapshot()},a=report.assessment;let evidence=g.decisions.filter(d=>Object.values(d.axes).some(v=>Math.abs(v)>=3)).slice(-10).reverse();return `<div class="political-banner"><div><span class="tag">${g.settlement?'任期结算':'治理档案预览'} / ${regime().name}</span><h2>${fmt(report.q/6)} 年，${report.q} 个季度的选择。</h2><p>${esc(report.reason)}<br>经济制度：${g.socialist?'非民主社会主义国家':'其他'} · 已记录 ${a.decisions} 项决策。${g.legacyHistory?'旧存档缺失历史指标显示为空缺，从升级时开始完整记录。':''}</p></div><button onclick="newDialog()">开启新历史 →</button></div><div class="section-label"><h3>与你最接近的三种统治倾向</h3><span>按契合度排序 · 不代表现实政治鉴定</span></div><div class="cards3 ideology-cards">${a.fits.map((f,i)=>`<div class="card"><span class="tag">${i+1} / 最相近倾向</span><div class="big-number">${f.percent}<small>%</small></div><h2>${f.name}</h2><div class="bar"><i style="width:${f.percent}%"></i></div></div>`).join('')}</div><div class="grid"><div class="card"><h3>评估依据</h3><p>契合度是游戏内相似度，不是三项相加等于 100% 的概率。系统将决策方向占 70%、最终政策与指标占 30%，生成九维治理画像，再与各倾向的目标画像比较：100 − 九维均方根距离。</p><p>本任期平均支持 ${fmt(a.averages.approval)}%，平均失业 ${fmt(a.averages.unemployment)}%，平均稳定 ${fmt(a.averages.stability)}。${a.vector[2]>65?'行政集中是你的重要手段。':a.vector[3]>65?'你较多选择司法保障与公开程序。':'你的治理方式保留了行政与协商之间的折中。'}${a.vector[1]>65?'民生和再分配占据较高优先级。':a.vector[0]>65?'市场开放和私人投资占据较高优先级。':'经济政策同时采用了国家干预与市场工具。'}</p>${AXES.map((k,i)=>`<div class="row"><span>${AXIS_NAMES[i]}</span><b>${fmt(a.vector[i],0)}/100</b></div>`).join('')}<p>社会主义扩展倾向仅对开局设定为“非民主社会主义国家”的国家开放；其中“国家社会主义”在本游戏指国家主导的社会主义经济。</p></div><div class="card"><h3>近期关键决策证据</h3>${evidence.map(d=>`<div class="news"><time>${date(d.q)}</time><div><h4>${esc(d.label)}</h4><p>${Object.entries(d.axes).filter(([k,v])=>v).map(([k,v])=>`${AXIS_NAMES[AXES.indexOf(k)]} ${v>0?'+':''}${v}`).join(' · ')}</p></div></div>`).join('')||'<p>尚无足够决策。当前结果主要反映制度与初始政策。</p>'}<details><summary>查看全部可用倾向与契合度</summary>${a.all.map(f=>`<div class="row"><span>${f.name}</span><b>${f.percent}%</b></div>`).join('')}</details></div></div>${historyCharts107(report.final)}`}
function showSettlementPrompt(){if(s.adminMode)return;let g=v3();if(s.ended){endDialog();return}modal(`<span class="tag">执政 ${fmt(s.q/6)} 年 / ${s.q} 季度</span><h2>是否为这段统治作结？</h2><p>你已经完成 ${s.q} 个季度。现在可以进入结算页面，查看完整经济、民意与制度走势，以及最接近的三种统治倾向。</p><p><b>选择继续后，每隔 12 个季度（2 年）会再次询问。</b>只要稳定度不低于 20 且未触发其他执政危机，就可以继续治理。继续会保留全部历史与政策，不重置任期数据。</p><button onclick="settlementChoice(false)">继续治理</button> <button class="primary" onclick="settlementChoice(true)">结束任期并结算</button>`)}
function settlementChoice(end){if(s.adminMode)return;let g=v3();g.settlementAsked=s.q;g.settlementDue=false;$('modal').close();if(end)beginSettlement('你选择结束执政并提交历史评估。');save();render()}
endDialog=function(){if(s.adminMode)return;if(!v3().settlement)beginSettlement(s.ended||'任期完成');$('modal').close();tab='settlement';save();render()};
function politicalMaintenance(){let p=pstate();p.ap=grantActionPoints();runCabinet();for(let x of p.promises.filter(x=>x.status==='pending')){let good=x.type==='retain'?p.memory.dismissals===x.dismissals:s.policies.education>=x.target;if((x.type!=='retain'&&good)||s.q>=x.deadline){x.status=good?'done':'broken';p.memory[good?'fulfilled':'broken']++;if(x.faction!==undefined)p.factions[x.faction].relation=clamp(p.factions[x.faction].relation+(good?8:-15),0,100);mod({approval:good?2:-4,stability:good?1:-2});noteDecision(good?'兑现承诺':'未兑现承诺',good?{law:1}: {populism:2});log(good?'承诺兑现':'承诺失信',x.label)}}if(p.judicial<35){mod({approval:p.judicial<20?-3:-2,stability:p.judicial<20?-3:-2});log('司法独立抗议','低司法独立持续损害支持和稳定。')}p.highCourtStreak=p.judicial>=70?p.highCourtStreak+1:0;if(!regime().democratic)mod({stability:(s.approval-55)*.08});completeReforms();if(regime().parliamentary&&p.confidenceLoss>=3&&s.approval<45)setGameEnd107('不信任案通过：连续三次议程失败且支持低于 45%。');checkPoliticalEnd()}
function finishQuarter(){let g=v3();if(!g.quarterOpen||pstate().current)return;g.quarterOpen=false;if(s.q%TERM===0){if(regime().election){if(s.situations?.transition?.q!==s.q)holdElection()}else{let result=electionForecast();let change=(result.total-50)*.15;mod({stability:change});log('统治基础评议',`地方加权认同 ${fmt(result.total)}%，稳定修正 ${fmt(change)}。`);g.regions.forEach(z=>z.termProgress=0)}}checkPoliticalEnd();record();if(s.ended){beginSettlement(s.ended);return}if(!s.adminMode&&regime().democratic&&constitutionalTermLimit()>0&&s.q>=constitutionalTermLimit()){beginSettlement('完成宪法规定的 '+constitutionalTermLimit()+' 季度执政期限。');return}if(!s.adminMode&&(!regime().democratic||constitutionalTermLimit()===0)&&s.q>=48&&(s.q-48)%12===0&&g.settlementAsked<s.q)g.settlementDue=true}

function economicQuarter(){let t=types[s.type];for(let k in s.policies)s.effective[k]+=(s.policies[k]-s.effective[k])*.35;let p=s.effective;s.capitalStock=clamp(s.capitalStock+(p.infrastructure-3.5)*.22,10,100);s.human=clamp(s.human+(p.education-4.5)*.12,10,100);s.world=clamp(s.world*.85+2.5*.15+(rand()-.5)*.8,-2,5);let shockG=0,shockI=0;for(let e of s.effects){shockG+=e.growth||0;shockI+=e.inflation||0;e.duration--}s.effects=s.effects.filter(e=>e.duration>0);let structural=s.reforms.reduce((a,r)=>a+(s.q>=r.ready?r.boost:0),0);let potential=t.potential+(s.capitalStock-50)*.022+(s.human-50)*.025+structural;let fiscal=(spend(p)-s.baselineSpend)*.12-(revenue(p)-s.baselineRevenue)*.1;let target=potential+fiscal-(s.rate-s.inflation-1)*.25+(s.confidence-65)*.015+(s.world-2.5)*t.open+shockG;s.growth=clamp(s.growth*.55+target*.45+(rand()-.5)*.5,-12,12);s.inflation=clamp(s.inflation*.82+2*.18+(s.growth-potential)*.13+shockI*.35-(s.rate-s.inflation-1)*.05,-2,150);s.unemployment=clamp(s.unemployment-(s.growth-potential)*.12+(6-s.unemployment)*.045,2,60);let oldRate=s.rate;s.rate=clamp(s.rate*.75+(.75+1.1*s.inflation+.3*(s.growth-potential))*.25,0,80);let deficit=-balance();s.debt=Math.max(0,s.debt+s.gdp*deficit/600);s.gdp*=1+(s.growth+s.inflation)/600;let ratio=s.debt/s.gdp*100;s.confidence=clamp(s.confidence*.85+(77-Math.max(0,ratio-65)*.35-Math.max(0,deficit-3)*2+(s.brake?4:0))*.15,5,98);s.yield=clamp(s.rate+Math.max(.3,(100-s.confidence)*.06)+Math.max(0,ratio-100)*.03,.4,100);let satisfaction=58+(s.growth-2)*3-(s.unemployment-6)*1.8-Math.abs(s.inflation-2)*2+(p.health-6)*1.3+(p.welfare-8)*1.3-(p.income-24)*.5;s.approval=clamp(s.approval*.88+satisfaction*.12,0,95);s.stability=clamp(s.stability*.93+(45+s.approval*.45+(p.security-3)*2)*.07,0,100);s.lastBalance=balance();if(s.brake&&balance()<-3){s.policies.infrastructure=Math.max(1,s.policies.infrastructure-.5);s.policies.welfare=Math.max(2,s.policies.welfare-.5);log('债务刹车触发','基建与福利预算各下调 0.5 个 GDP 百分点。');draft={...s.policies}}s.lastNews=`央行${s.rate>oldRate+.08?'加息':s.rate<oldRate-.08?'降息':'维持利率附近'}至 ${fmt(s.rate)}%，回应通胀与产出变化。`;log('季度经济公报',`增长 ${fmt(s.growth)}%，通胀 ${fmt(s.inflation)}%。${s.lastNews}`);}
advance=function(){initPolitics();let g=v3();checkPoliticalEnd();if(s.ended&&!g.settlement)beginSettlement(s.ended);if(s.ended){save();render();endDialog();return}if(pstate().current){showPoliticalEvent();return}if(g.settlementDue){showSettlementPrompt();return}if(!s.adminMode&&regime().democratic&&constitutionalTermLimit()>0&&s.q>=constitutionalTermLimit()){beginSettlement('本存档已达到宪法规定的任期上限，进入结算。');save();render();return}s.q++;g.quarterOpen=true;economicQuarter();politicalMaintenance();if(s.debt/s.gdp>1.9&&s.confidence<25)setGameEnd107('债务危机：政府失去可持续融资渠道。');record();if(s.ended){beginSettlement(s.ended);save();render();return}queueQuarterEvents();save();render();showPoliticalEvent()};
const basePSave=pSave;pSave=function(){if(s?.governance)record();basePSave()};
const baseCreate=create;create=function(seed){baseCreate(seed);record();save();render()};
const baseValid=validSave;validSave=function(v){let copy={...v};if(v?.political?.bill?.kind==='reform'){copy.political={...v.political,bill:null};if(!REFORMS[v.political.bill.id])return false}if(!baseValid(copy))return false;let g=v.governance;if(g){if(g.version!==3||!Array.isArray(g.regions)||![7,8].includes(g.regions.length)||!Array.isArray(g.elections)||!Array.isArray(g.offers)||!Array.isArray(g.decisions)||!g.axisSum||!g.termActions)return false;for(let k of ['axisCount','nextOffer','cycle','eventsChosen','eventsGenerated','settlementAsked','sports','culture','fund'])if(!Number.isFinite(g[k]))return false;for(let k of AXES)if(!Number.isFinite(g.axisSum[k]))return false;if(g.regions.some((z,i)=>z.id!==i||typeof z.name!=='string'||!Number.isFinite(z.weight)||!Number.isFinite(z.termProgress)||!Number.isFinite(z.development)||!Number.isFinite(z.attitude)))return false;if(g.offers.some(o=>!REFORMS[o.catalog]||!Number.isInteger(o.uid)))return false;if(v.reforms.some(x=>!REFORMS[x.id]||!Number.isFinite(x.ready)))return false}return true};
const OLD_KEY=KEY,BACKUP_KEY=KEY+'-pre-v3';
function migratePending(){let p=pstate();if(s.pending!==null){let old=events[s.pending];if(old)pushEvent({type:'economy',title:old.title,text:old.text,options:old.options.map(o=>option(o[0],o[1],o[2]))});s.pending=null}if(s.ended&&!v3().settlement)beginSettlement(s.ended);if(!s.ended&&regime().democratic&&constitutionalTermLimit()>0&&s.q>=constitutionalTermLimit())beginSettlement('旧存档已达到宪法规定的任期上限。')}
importSave=function(input){let f=input.files[0];if(!f)return;if(f.size>15000000){toast('存档过大，未导入');return}f.text().then(txt=>{let obj=JSON.parse(txt);if(obj.version!==1||!validSave(obj.state))throw Error();s=obj.state;draft={...s.policies};initPolitics();migratePending();record();save();render();toast('存档已恢复，旧版政治数据自动迁移')}).catch(()=>toast('存档无效，当前进度保持不变'))};
newDialog=function(){modal(`<span class="tag">国策 1.0.7 / 新历史</span><h2>选择制度，开始新的任期。</h2><p>每年 6 季度，每届 24 季度。民主国家最多两届；非民主国家第 48 季度后可选择继续，每 12 季度再次询问。新局覆盖自动存档，可先在国家档案导出。</p><label for="regime">政治体制</label><select id="regime"><option value="random">随机政体</option>${REGIMES.map(r=>`<option value="${r.id}">${r.name} · ${r.player}</option>`).join('')}</select><label for="model">经济模式（暂未完工）</label><select id="model" disabled aria-describedby="model-status"><option value="mixed" selected>混合所有制经济</option></select><p class="note" id="model-status">经济模式暂未完工，新世界统一采用混合所有制经济。</p><label for="seed">世界种子</label><input id="seed" maxlength="40" value="${Math.floor(Math.random()*999999)}"><div class="row"><button onclick="$('modal').close()">返回</button><button class="primary" onclick="selectedRegime=$('regime').value;pendingModel='mixed';let v=$('seed').value.trim()||'new-state';$('modal').close();tab='overview';create(v)">生成国家 →</button></div>`)};
overview=function(){let p=pstate(),g=v3(),r=regime();return `<div class="political-banner"><div><span class="tag">国策 1.0.7 / <span data-guide="regime">${r.name}</span> / <span data-guide="player">${r.player}</span></span><h2 data-guide="country">${s.name}</h2><p>${r.note}<br>已执政 ${fmt(s.q/6)} 年 · ${s.q} 季度；${r.democratic?'两届任期共 48 季度。':'第 48 季度可结算，此后每 12 季度再次询问。'}每季度至少 3 件决策事件。</p></div><div class="action-count"><b>${p.ap}</b><span>本季政治行动点</span><small class="action-mode-status">${actionPointsSummary()}</small></div></div><div class="metrics political-metrics">${metric('公众支持',fmt(s.approval),'%',`加权地区预测 ${fmt(electionForecast().total)}%`,s.approval>50)}${metric('政治稳定',fmt(s.stability),'/100','低于 20 将结束游戏',s.stability>=40)}${metric('司法独立',fmt(p.judicial),'/100','高独立增加审查，低独立引发抗议',p.judicial>=35)}${metric('本季已回复事件',g.eventsChosen,'件',`待决 ${p.queue.length+(p.current?1:0)} 件`)}</div><div class="quick-actions"><button onclick="changeTab('assembly')">${r.body} →</button><button onclick="changeTab('cabinet')">内阁与人事 →</button><button onclick="changeTab('politics')">地区选情 →</button><button onclick="changeTab('archive')">国家历史图表 →</button></div><div class="metrics">${metric('实际年化增长',fmt(s.growth),'%','经济增长',s.growth>0)}${metric('失业率',fmt(s.unemployment),'%','就业状况',s.unemployment<8)}${metric('通胀',fmt(s.inflation),'%','央行目标 2%',s.inflation<4)}${metric('债务 / GDP',fmt(s.debt/s.gdp*100),'%',`信用评级 ${rating()}`,s.debt/s.gdp<.9)}</div><div class="grid"><div class="card"><h3>增长轨迹</h3>${seriesChart('growth','增长率')}<p><span data-guide="gdp">名义 GDP ${fmt(s.gdp)} 十亿元</span> · <span data-guide="population">人口 ${fmt(s.pop)} 百万人</span> · <span data-guide="balance">财政余额 ${fmt(balance())}% GDP</span></p></div><div class="card"><h3>${executiveName()}简报</h3>${governmentBriefings(4).map(l=>`<div class="news"><time>${date(l.q)}</time><div><h4>${esc(l.title)}</h4><p>${esc(l.text)}</p></div></div>`).join('')}</div></div>`};
render=function(){initPolitics();let r=regime();let list=[...politicalTabs,['settlement','◷','任期评估']];if(!list.some(x=>x[0]===tab))tab='overview';$('heading').textContent=tab==='assembly'?r.body:tab==='judiciary'?r.court:list.find(x=>x[0]===tab)[2];$('date').textContent=date();$('advance').innerHTML=s.ended?'查看任期结算 →':pstate().current?'回复季度事件 →':v3().settlementDue?'选择结算或继续 →':'推进季度 →';$('nav').innerHTML=list.map(t=>`<button class="${tab===t[0]?'active':''}" onclick="changeTab('${t[0]}')"><span>${t[1]}</span>${t[0]==='assembly'?r.body:t[2]}</button>`).join('');$('content').innerHTML=({overview,assembly,cabinet,judiciary,politics,budget,reforms:policies,archive,settlement:settlementPage})[tab]()};
showHelp=function(){modal(`<span class="tag">国策 1.0.7 / 治理指南</span><h2>政策、承诺与选票相互作用。</h2><p>每年 6 季度，每届 24 季度。民主国家在第 24、48 季度举行单轮两方选举，按地区人口权重计算全国票率，超过 50% 胜选；第二届结束自动结算。非民主国家第 48 季度可选择继续，此后每 12 季度再询问。稳定低于 20 或严重债务危机会提前结束。</p><p>每季度至少 3 件经济、政治或其他事件。先回复所有事件，再进行选举与任期结算；事件不耗政治行动点。预算、改革仍须权力机关通过，每季会见、协商、任免、提案推进与表决共享行动点；初始每季 3 点，科研升级可提高至 6 点。</p><p>每个党团仅一名总召。成员与官员有九类政治倾向。地区诉求未回应最多将该地得票率乘以 80%，政策选择、内阁任务与改革都能改变契合度。选举页显示地区情况、当前预测与历次实际结果。</p><p>每 6 季度轮换改革草案，轮换前有确认事件。未查看的草案替换，已查看、已提交和执行中的项目保留。改革完成后兑现效果，特殊遗产税仅能使用一次。</p><p>结算页展示 12 项完整折线图和三种最接近的统治倾向。契合度依据实际决策和最终数据，非随机判定。非民主社会主义国家额外开放四种社会主义倾向。旧版存档缺失的历史值不补造。</p><button class="primary" onclick="$('modal').close()">返回政府</button>`)};
$('modal').addEventListener('cancel',e=>{if(s?.governance?.settlementDue)e.preventDefault()});
function bootGame(){try{let raw=localStorage.getItem(KEY);if(raw){let v=JSON.parse(raw);if(!validSave(v))throw Error('Invalid saved state');if(!v.governance)localStorage.setItem(BACKUP_KEY,raw);s=v;draft={...s.policies};initPolitics();migratePending();record();save();render()}else create(String(Math.floor(Math.random()*999999)))}catch(err){console.error('Save loading failed',err);let raw=localStorage.getItem(KEY);if(raw)try{localStorage.setItem(KEY+'-recovery',raw)}catch(_){}create('new-governance');toast('旧存档暂未能载入，已保留恢复副本。')}

}
